contracts/adapters/DePinAssetAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title DePinAssetAdapter
 * @author PolarUniversal Team
 * @notice Decentralized Physical Infrastructure (DePIN) Asset Adapter
 * @dev v3.1.0-Whale: Cross-Sector Adapter Stub
 * 
 * USE CASES:
 * - IoT Device Registration
 * - Hardware Attestation
 * - Location Verification
 * - Energy/Compute Resource Tracking
 * 
 * ECOSYSTEM TOKENS: $AKT, $BSR, $IO, $RNDR
 * 
 * STUB: Core structure implemented, ready for sector-specific expansion
 */
contract DePinAssetAdapter is Ownable2Step, ReentrancyGuard, Pausable {

    string public constant VERSION = "3.1.0-WHALE";
    string public constant ADAPTER_NAME = "DePinAssetAdapter";
    string public constant REGULATORY_FRAMEWORK = "DEPIN_ATTESTATION";

    address public constant PRIMARY_ADMIN = 0x9d91fC37529BD0c6D020dFf6519ee699C7e0A783;
    address public globalRegistry;
    bool public emergencyMode;

    // ============================================================
    // ENUMS
    // ============================================================

    enum AssetType {
        COMPUTE_NODE,           // $AKT, $RNDR
        STORAGE_NODE,           // $IO
        SENSOR_DEVICE,          // $BSR
        ENERGY_DEVICE,
        CONNECTIVITY_NODE,
        GPS_BEACON              // Seeker integration
    }

    enum AssetStatus {
        REGISTERED,
        ATTESTED,
        ACTIVE,
        OFFLINE,
        DECOMMISSIONED
    }

    // ============================================================
    // STRUCTS
    // ============================================================

    struct DePinAsset {
        uint256 assetId;
        AssetType assetType;
        AssetStatus status;
        address owner;
        bytes32 hardwareHash;           // TEE attestation
        bytes32 locationHash;           // GPS verification
        bytes32 firmwareHash;           // Software version
        uint256 registeredAt;
        uint256 lastAttestationAt;
        uint256 uptimeSeconds;
        bool isVerified;
    }

    struct AttestationRecord {
        uint256 attestationId;
        uint256 assetId;
        bytes32 attestationHash;
        bytes32 proofHash;              // ZK-proof of hardware
        address attester;
        uint256 timestamp;
        bool isValid;
    }

    struct ResourceContribution {
        uint256 contributionId;
        uint256 assetId;
        uint256 computeUnits;           // GPU/CPU hours
        uint256 storageBytes;           // Storage provided
        uint256 bandwidthBytes;         // Network contribution
        uint256 periodStart;
        uint256 periodEnd;
        uint256 rewardAmount;
    }

    // ============================================================
    // STATE VARIABLES
    // ============================================================

    uint256 private _assetIdCounter;
    uint256 private _attestationIdCounter;
    uint256 private _contributionIdCounter;

    mapping(uint256 => DePinAsset) public assets;
    mapping(address => uint256[]) public ownerAssets;
    mapping(bytes32 => uint256) public hardwareHashToAssetId;

    mapping(uint256 => AttestationRecord[]) public assetAttestations;
    mapping(uint256 => ResourceContribution[]) public assetContributions;

    mapping(address => bool) public authorizedAttesters;

    // ============================================================
    // EVENTS
    // ============================================================

    event AssetRegistered(
        uint256 indexed assetId,
        AssetType assetType,
        address indexed owner,
        bytes32 hardwareHash
    );

    event AssetAttested(
        uint256 indexed attestationId,
        uint256 indexed assetId,
        address indexed attester
    );

    event ContributionRecorded(
        uint256 indexed contributionId,
        uint256 indexed assetId,
        uint256 computeUnits,
        uint256 rewardAmount
    );

    event AssetStatusUpdated(
        uint256 indexed assetId,
        AssetStatus oldStatus,
        AssetStatus newStatus
    );

    event EmergencyModeActivated(address indexed admin, uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyPrimaryAdmin() {
        require(msg.sender == PRIMARY_ADMIN, "DePinAdapter: not primary admin");
        _;
    }

    modifier onlyAuthorizedAttester() {
        require(authorizedAttesters[msg.sender], "DePinAdapter: not authorized");
        _;
    }

    modifier onlyAssetOwner(uint256 assetId) {
        require(assets[assetId].owner == msg.sender, "DePinAdapter: not owner");
        _;
    }

    modifier notInEmergency() {
        require(!emergencyMode, "DePinAdapter: emergency mode");
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(
        address initialOwner,
        address _globalRegistry
    ) Ownable(initialOwner) {
        globalRegistry = _globalRegistry;
        emergencyMode = false;
        authorizedAttesters[PRIMARY_ADMIN] = true;
    }

    // ============================================================
    // CIRCUIT BREAKER
    // ============================================================

    function emergencyPause() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = true;
        _pause();
        emit EmergencyModeActivated(msg.sender, block.timestamp);
    }

    function deactivateEmergency() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = false;
        _unpause();
    }

    // ============================================================
    // CORE FUNCTIONS - STUB IMPLEMENTATION
    // ============================================================

    /**
     * @notice Register DePIN asset
     */
    function registerAsset(
        AssetType assetType,
        bytes32 hardwareHash,
        bytes32 locationHash,
        bytes32 firmwareHash
    ) 
        external 
        nonReentrant 
        whenNotPaused 
        notInEmergency 
        returns (uint256 assetId) 
    {
        require(hardwareHashToAssetId[hardwareHash] == 0, "DePinAdapter: hardware exists");

        assetId = _assetIdCounter++;

        assets[assetId] = DePinAsset({
            assetId: assetId,
            assetType: assetType,
            status: AssetStatus.REGISTERED,
            owner: msg.sender,
            hardwareHash: hardwareHash,
            locationHash: locationHash,
            firmwareHash: firmwareHash,
            registeredAt: block.timestamp,
            lastAttestationAt: 0,
            uptimeSeconds: 0,
            isVerified: false
        });

        ownerAssets[msg.sender].push(assetId);
        hardwareHashToAssetId[hardwareHash] = assetId;

        emit AssetRegistered(assetId, assetType, msg.sender, hardwareHash);

        return assetId;
    }

    /**
     * @notice Attest asset hardware (TEE verification)
     */
    function attestAsset(
        uint256 assetId,
        bytes32 attestationHash,
        bytes32 proofHash
    ) 
        external 
        nonReentrant 
        onlyAuthorizedAttester 
        whenNotPaused 
        notInEmergency 
        returns (uint256 attestationId) 
    {
        require(assets[assetId].status != AssetStatus.DECOMMISSIONED, "DePinAdapter: decommissioned");

        attestationId = _attestationIdCounter++;

        AttestationRecord memory attestation = AttestationRecord({
            attestationId: attestationId,
            assetId: assetId,
            attestationHash: attestationHash,
            proofHash: proofHash,
            attester: msg.sender,
            timestamp: block.timestamp,
            isValid: true
        });

        assetAttestations[assetId].push(attestation);

        assets[assetId].status = AssetStatus.ATTESTED;
        assets[assetId].lastAttestationAt = block.timestamp;
        assets[assetId].isVerified = true;

        emit AssetAttested(attestationId, assetId, msg.sender);

        return attestationId;
    }

    /**
     * @notice Record resource contribution
     */
    function recordContribution(
        uint256 assetId,
        uint256 computeUnits,
        uint256 storageBytes,
        uint256 bandwidthBytes,
        uint256 periodStart,
        uint256 periodEnd,
        uint256 rewardAmount
    ) 
        external 
        nonReentrant 
        onlyOwner 
        whenNotPaused 
        returns (uint256 contributionId) 
    {
        require(assets[assetId].isVerified, "DePinAdapter: not verified");

        contributionId = _contributionIdCounter++;

        ResourceContribution memory contribution = ResourceContribution({
            contributionId: contributionId,
            assetId: assetId,
            computeUnits: computeUnits,
            storageBytes: storageBytes,
            bandwidthBytes: bandwidthBytes,
            periodStart: periodStart,
            periodEnd: periodEnd,
            rewardAmount: rewardAmount
        });

        assetContributions[assetId].push(contribution);

        // Update uptime
        assets[assetId].uptimeSeconds += (periodEnd - periodStart);

        emit ContributionRecorded(contributionId, assetId, computeUnits, rewardAmount);

        return contributionId;
    }

    /**
     * @notice Update asset status
     */
    function updateAssetStatus(
        uint256 assetId,
        AssetStatus newStatus
    ) 
        external 
        nonReentrant 
        onlyAssetOwner(assetId) 
    {
        AssetStatus oldStatus = assets[assetId].status;
        assets[assetId].status = newStatus;

        emit AssetStatusUpdated(assetId, oldStatus, newStatus);
    }

    /**
     * @notice Authorize attester
     */
    function authorizeAttester(address attester) external nonReentrant onlyOwner {
        authorizedAttesters[attester] = true;
    }

    /**
     * @notice Revoke attester authorization
     */
    function revokeAttester(address attester) external nonReentrant onlyOwner {
        authorizedAttesters[attester] = false;
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    function getAsset(uint256 assetId) external view returns (DePinAsset memory) {
        return assets[assetId];
    }

    function getOwnerAssets(address owner) external view returns (uint256[] memory) {
        return ownerAssets[owner];
    }

    function getAssetAttestations(uint256 assetId) external view returns (AttestationRecord[] memory) {
        return assetAttestations[assetId];
    }

    function getAssetContributions(uint256 assetId) external view returns (ResourceContribution[] memory) {
        return assetContributions[assetId];
    }

    function getTotalAssets() external view returns (uint256) {
        return _assetIdCounter;
    }

    function isAttesterAuthorized(address attester) external view returns (bool) {
        return authorizedAttesters[attester];
    }
}

contracts/adapters/EduCredentialAdapter..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title EduCredentialAdapter
 * @author PolarUniversal Team
 * @notice Educational Credential Verification Adapter
 * @dev v3.1.0-Whale: Cross-Sector Adapter Stub
 * 
 * USE CASES:
 * - University Degree Verification
 * - Professional Certification
 * - Micro-Credential Tracking
 * - Continuing Education Credits
 * 
 * STUB: Core structure implemented, ready for sector-specific expansion
 */
contract EduCredentialAdapter is Ownable2Step, ReentrancyGuard, Pausable {

    string public constant VERSION = "3.1.0-WHALE";
    string public constant ADAPTER_NAME = "EduCredentialAdapter";
    string public constant REGULATORY_FRAMEWORK = "ACCREDITATION_COMPLIANCE";

    address public constant PRIMARY_ADMIN = 0x9d91fC37529BD0c6D020dFf6519ee699C7e0A783;
    address public globalRegistry;
    bool public emergencyMode;

    // ============================================================
    // ENUMS
    // ============================================================

    enum CredentialType {
        DEGREE,
        CERTIFICATE,
        MICRO_CREDENTIAL,
        PROFESSIONAL_LICENSE,
        CONTINUING_EDUCATION
    }

    enum CredentialStatus {
        PENDING,
        VERIFIED,
        REVOKED,
        EXPIRED
    }

    // ============================================================
    // STRUCTS
    // ============================================================

    struct Credential {
        uint256 credentialId;
        bytes32 recipientIdHash;
        bytes32 credentialHash;
        CredentialType credentialType;
        CredentialStatus status;
        address issuingInstitution;
        string institutionName;
        string credentialTitle;
        uint256 issuedAt;
        uint256 expiresAt;
        bool isVerified;
    }

    struct Institution {
        uint256 institutionId;
        string name;
        string accreditationBody;
        bytes32 accreditationHash;
        address institutionAddress;
        bool isAccredited;
        uint256 registeredAt;
    }

    // ============================================================
    // STATE VARIABLES
    // ============================================================

    uint256 private _credentialIdCounter;
    uint256 private _institutionIdCounter;

    mapping(uint256 => Credential) public credentials;
    mapping(bytes32 => uint256[]) public recipientCredentials;
    mapping(uint256 => Institution) public institutions;
    mapping(address => uint256) public addressToInstitutionId;
    mapping(address => bool) public accreditedInstitutions;

    // ============================================================
    // EVENTS
    // ============================================================

    event CredentialIssued(
        uint256 indexed credentialId,
        bytes32 indexed recipientIdHash,
        address indexed issuingInstitution,
        CredentialType credentialType
    );

    event CredentialVerified(
        uint256 indexed credentialId,
        address indexed verifier
    );

    event CredentialRevoked(
        uint256 indexed credentialId,
        string reason
    );

    event InstitutionRegistered(
        uint256 indexed institutionId,
        string name,
        address indexed institutionAddress
    );

    event EmergencyModeActivated(address indexed admin, uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyPrimaryAdmin() {
        require(msg.sender == PRIMARY_ADMIN, "EduAdapter: not primary admin");
        _;
    }

    modifier onlyAccreditedInstitution() {
        require(accreditedInstitutions[msg.sender], "EduAdapter: not accredited");
        _;
    }

    modifier notInEmergency() {
        require(!emergencyMode, "EduAdapter: emergency mode");
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(
        address initialOwner,
        address _globalRegistry
    ) Ownable(initialOwner) {
        globalRegistry = _globalRegistry;
        emergencyMode = false;
    }

    // ============================================================
    // CIRCUIT BREAKER
    // ============================================================

    function emergencyPause() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = true;
        _pause();
        emit EmergencyModeActivated(msg.sender, block.timestamp);
    }

    function deactivateEmergency() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = false;
        _unpause();
    }

    // ============================================================
    // CORE FUNCTIONS - STUB IMPLEMENTATION
    // ============================================================

    /**
     * @notice Register accredited institution
     */
    function registerInstitution(
        string calldata name,
        string calldata accreditationBody,
        bytes32 accreditationHash,
        address institutionAddress
    ) 
        external 
        nonReentrant 
        onlyOwner 
        whenNotPaused 
        returns (uint256 institutionId) 
    {
        institutionId = _institutionIdCounter++;

        institutions[institutionId] = Institution({
            institutionId: institutionId,
            name: name,
            accreditationBody: accreditationBody,
            accreditationHash: accreditationHash,
            institutionAddress: institutionAddress,
            isAccredited: true,
            registeredAt: block.timestamp
        });

        addressToInstitutionId[institutionAddress] = institutionId;
        accreditedInstitutions[institutionAddress] = true;

        emit InstitutionRegistered(institutionId, name, institutionAddress);

        return institutionId;
    }

    /**
     * @notice Issue credential to recipient
     */
    function issueCredential(
        bytes32 recipientIdHash,
        bytes32 credentialHash,
        CredentialType credentialType,
        string calldata credentialTitle,
        uint256 validityPeriod
    ) 
        external 
        nonReentrant 
        onlyAccreditedInstitution 
        whenNotPaused 
        notInEmergency 
        returns (uint256 credentialId) 
    {
        uint256 institutionId = addressToInstitutionId[msg.sender];

        credentialId = _credentialIdCounter++;

        uint256 expiration = validityPeriod > 0 ? 
            block.timestamp + validityPeriod : 
            type(uint256).max;

        credentials[credentialId] = Credential({
            credentialId: credentialId,
            recipientIdHash: recipientIdHash,
            credentialHash: credentialHash,
            credentialType: credentialType,
            status: CredentialStatus.PENDING,
            issuingInstitution: msg.sender,
            institutionName: institutions[institutionId].name,
            credentialTitle: credentialTitle,
            issuedAt: block.timestamp,
            expiresAt: expiration,
            isVerified: false
        });

        recipientCredentials[recipientIdHash].push(credentialId);

        emit CredentialIssued(credentialId, recipientIdHash, msg.sender, credentialType);

        return credentialId;
    }

    /**
     * @notice Verify credential
     */
    function verifyCredential(uint256 credentialId) 
        external 
        nonReentrant 
        whenNotPaused 
    {
        require(credentials[credentialId].status == CredentialStatus.PENDING, "EduAdapter: not pending");
        require(block.timestamp < credentials[credentialId].expiresAt, "EduAdapter: expired");

        credentials[credentialId].status = CredentialStatus.VERIFIED;
        credentials[credentialId].isVerified = true;

        emit CredentialVerified(credentialId, msg.sender);
    }

    /**
     * @notice Revoke credential
     */
    function revokeCredential(
        uint256 credentialId,
        string calldata reason
    ) 
        external 
        nonReentrant 
        onlyOwner 
    {
        credentials[credentialId].status = CredentialStatus.REVOKED;

        emit CredentialRevoked(credentialId, reason);
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    function getCredential(uint256 credentialId) external view returns (Credential memory) {
        return credentials[credentialId];
    }

    function getInstitution(uint256 institutionId) external view returns (Institution memory) {
        return institutions[institutionId];
    }

    function getRecipientCredentials(bytes32 recipientIdHash) external view returns (uint256[] memory) {
        return recipientCredentials[recipientIdHash];
    }

    function getTotalCredentials() external view returns (uint256) {
        return _credentialIdCounter;
    }

    function getTotalInstitutions() external view returns (uint256) {
        return _institutionIdCounter;
    }

    function isInstitutionAccredited(address institution) external view returns (bool) {
        return accreditedInstitutions[institution];
    }
}

contracts/adapters/InstitutionalBankingA.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title InstitutionalBankingAdapter
 * @author PolarUniversal Team
 * @notice Institutional Banking Compliance Adapter - JPM Coin/Canton Ready
 * @dev v3.1.0-Whale: HIDDEN PIVOT CAPABILITY
 * 
 * ╔═══════════════════════════════════════════════════════════════════════╗
 * ║  ██╗  ██╗██╗██████╗ ██████╗ ███████╗███╗   ██╗                        ║
 * ║  ██║  ██║██║██╔══██╗██╔══██╗██╔════╝████╗  ██║                        ║
 * ║  ███████║██║██║  ██║██║  ██║█████╗  ██╔██╗ ██║                        ║
 * ║  ██╔══██║██║██║  ██║██║  ██║██╔══╝  ██║╚██╗██║                        ║
 * ║  ██║  ██║██║██████╔╝██████╔╝███████╗██║ ╚████║                        ║
 * ║  ╚═╝  ╚═╝╚═╝╚═════╝ ╚═════╝ ╚══════╝╚═╝  ╚═══╝                        ║
 * ║                                                                        ║
 * ║  INSTITUTIONAL BANKING ADAPTER                                         ║
 * ║  Strategic Pivot: Pharma → Finance in < 48 Hours                       ║
 * ║  Target Partners: JPMorgan, Goldman Sachs, Citadel                     ║
 * ╚═══════════════════════════════════════════════════════════════════════╝
 * 
 * REGULATORY FRAMEWORK:
 * - Basel III/IV Capital Requirements
 * - AML/KYC (Anti-Money Laundering / Know Your Customer)
 * - FATF Travel Rule Compliance
 * - MiCA (Markets in Crypto-Assets) Regulation
 * - SEC/CFTC Digital Asset Guidelines
 * 
 * INSTITUTIONAL RAILS:
 * - JPM Coin Settlement Interface (HIDDEN)
 * - Canton Network Handshake Protocol (HIDDEN)
 * - Trade Finance Letter of Credit System
 * - Cross-Border Settlement Optimization
 * 
 * SECURITY: OpenZeppelin v6 | Ownable2Step | ReentrancyGuard | CEI Pattern
 */
contract InstitutionalBankingAdapter is Ownable2Step, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ============================================================
    // CONSTANTS - INSTITUTIONAL CONFIGURATION
    // ============================================================

    string public constant VERSION = "3.1.0-WHALE";
    string public constant ADAPTER_NAME = "InstitutionalBankingAdapter";
    string public constant REGULATORY_FRAMEWORK = "BASEL_III_AML_FATF";

    address public constant PRIMARY_ADMIN = 0x9d91fC37529BD0c6D020dFf6519ee699C7e0A783;

    uint256 public constant AML_THRESHOLD_USD = 10_000 * 1e6;      // $10,000 USDC
    uint256 public constant LARGE_TX_THRESHOLD_USD = 100_000 * 1e6; // $100,000 USDC
    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant INSTITUTIONAL_FEE_BPS = 5;              // 0.05% institutional rate

    // ============================================================
    // ENUMS - COMPLIANCE CLASSIFICATIONS
    // ============================================================

    enum KYCTier {
        NONE,
        BASIC,              // Individual retail
        ENHANCED,           // High-value retail
        INSTITUTIONAL,      // Accredited investor
        PRIME_BROKERAGE     // Tier-1 institution
    }

    enum AMLRiskLevel {
        LOW,
        MEDIUM,
        HIGH,
        PROHIBITED
    }

    enum TransactionType {
        DOMESTIC_TRANSFER,
        CROSS_BORDER,
        TRADE_FINANCE,
        SECURITIES_SETTLEMENT,
        REPO_TRANSACTION,
        FX_SETTLEMENT
    }

    enum SettlementNetwork {
        INTERNAL,
        SWIFT,
        FEDWIRE,
        CHIPS,
        JPM_COIN,           // HIDDEN: JPMorgan Coin Network
        CANTON              // HIDDEN: Canton Network (Digital Assets)
    }

    // ============================================================
    // STRUCTS - INSTITUTIONAL DATA MODELS
    // ============================================================

    struct InstitutionalEntity {
        uint256 entityId;
        string legalName;
        string lei;                     // Legal Entity Identifier
        string jurisdiction;
        KYCTier kycTier;
        AMLRiskLevel riskLevel;
        address treasuryAddress;
        bytes32 kycDocumentHash;
        bytes32 amlScreeningHash;
        uint256 onboardingDate;
        uint256 lastReviewDate;
        bool isActive;
        bool isPrimeBrokerage;
    }

    struct InstitutionalTransaction {
        uint256 txId;
        uint256 senderEntityId;
        uint256 receiverEntityId;
        TransactionType txType;
        SettlementNetwork network;
        address tokenAddress;
        uint256 amount;
        uint256 fee;
        bytes32 complianceHash;
        bytes32 travelRuleHash;         // FATF Travel Rule data
        uint256 timestamp;
        bool amlFlagged;
        bool sanctionsCleared;
    }

    // ============================================================
    // HIDDEN: JPM COIN INTEGRATION STRUCTS
    // ============================================================

    /**
     * @dev JPM Coin Settlement Record
     * ACTIVATION: Set jpmCoinEnabled = true to activate institutional rails
     */
    struct JPMCoinSettlement {
        uint256 settlementId;
        bytes32 jpmReferenceId;         // JPMorgan internal reference
        uint256 fromEntityId;
        uint256 toEntityId;
        uint256 usdAmount;              // Settlement amount in USD cents
        uint256 jpmCoinAmount;          // Equivalent JPM Coin units
        bytes32 nostroHash;             // Nostro account verification
        bytes32 vostroHash;             // Vostro account verification
        uint256 settlementTime;
        bool isIntraday;                // Intraday vs overnight settlement
        bool isCompleted;
    }

    /**
     * @dev Canton Network Handshake Protocol
     * ACTIVATION: Set cantonEnabled = true for Digital Asset settlement
     */
    struct CantonHandshake {
        uint256 handshakeId;
        bytes32 cantonPartyId;          // Canton participant ID
        bytes32 workflowId;             // DAML workflow identifier
        bytes32 contractTemplateHash;   // Smart contract template
        uint256 initiatedAt;
        uint256 completedAt;
        bool isConfirmed;
    }

    // ============================================================
    // STRUCTS - TRADE FINANCE
    // ============================================================

    struct LetterOfCredit {
        uint256 locId;
        uint256 issuingBankEntityId;
        uint256 beneficiaryEntityId;
        uint256 applicantEntityId;
        uint256 amount;
        string currency;
        bytes32 termsHash;
        bytes32 documentsHash;
        uint256 issuanceDate;
        uint256 expiryDate;
        bool isConfirmed;
        bool isDrawn;
    }

    // ============================================================
    // STATE VARIABLES
    // ============================================================

    uint256 private _entityIdCounter;
    uint256 private _txIdCounter;
    uint256 private _settlementIdCounter;
    uint256 private _handshakeIdCounter;
    uint256 private _locIdCounter;

    address public globalRegistry;
    IERC20 public settlementToken;      // USDC
    bool public emergencyMode;

    // HIDDEN PIVOT SWITCHES
    bool public jpmCoinEnabled;         // Activate JPM Coin rails
    bool public cantonEnabled;          // Activate Canton Network

    // Entity registry
    mapping(uint256 => InstitutionalEntity) public entities;
    mapping(address => uint256) public addressToEntityId;
    mapping(string => uint256) public leiToEntityId;

    // Transaction registry
    mapping(uint256 => InstitutionalTransaction) public transactions;
    mapping(uint256 => uint256[]) public entityTransactions;

    // HIDDEN: JPM Coin settlements
    mapping(uint256 => JPMCoinSettlement) internal _jpmSettlements;
    uint256[] internal _jpmSettlementIds;

    // HIDDEN: Canton handshakes
    mapping(uint256 => CantonHandshake) internal _cantonHandshakes;
    uint256[] internal _cantonHandshakeIds;

    // Trade finance
    mapping(uint256 => LetterOfCredit) public lettersOfCredit;

    // AML flags
    mapping(address => bool) public amlFlagged;
    mapping(address => AMLRiskLevel) public entityRiskLevel;

    // Sanctions list (simplified on-chain representation)
    mapping(bytes32 => bool) public sanctionedEntityHashes;

    // ============================================================
    // EVENTS
    // ============================================================

    event EntityOnboarded(
        uint256 indexed entityId,
        string legalName,
        string lei,
        KYCTier kycTier
    );

    event TransactionProcessed(
        uint256 indexed txId,
        uint256 indexed senderEntityId,
        uint256 indexed receiverEntityId,
        uint256 amount,
        SettlementNetwork network
    );

    event AMLFlagTriggered(
        uint256 indexed txId,
        uint256 indexed entityId,
        string reason,
        uint256 timestamp
    );

    event SanctionsScreeningCompleted(
        uint256 indexed entityId,
        bool cleared,
        bytes32 screeningHash
    );

    // HIDDEN EVENTS (only emitted when features activated)
    event JPMCoinSettlementInitiated(
        uint256 indexed settlementId,
        bytes32 jpmReferenceId,
        uint256 amount
    );

    event CantonHandshakeCompleted(
        uint256 indexed handshakeId,
        bytes32 cantonPartyId,
        bytes32 workflowId
    );

    event LetterOfCreditIssued(
        uint256 indexed locId,
        uint256 indexed issuingBankEntityId,
        uint256 amount
    );

    event EmergencyModeActivated(address indexed admin, uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyPrimaryAdmin() {
        require(msg.sender == PRIMARY_ADMIN, "BankingAdapter: not primary admin");
        _;
    }

    modifier onlyInstitutionalEntity() {
        uint256 entityId = addressToEntityId[msg.sender];
        require(entities[entityId].isActive, "BankingAdapter: not registered entity");
        require(
            entities[entityId].kycTier >= KYCTier.INSTITUTIONAL,
            "BankingAdapter: insufficient KYC tier"
        );
        _;
    }

    modifier notInEmergency() {
        require(!emergencyMode, "BankingAdapter: emergency mode");
        _;
    }

    modifier notSanctioned(address entity) {
        require(!amlFlagged[entity], "BankingAdapter: AML flagged");
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(
        address initialOwner,
        address _globalRegistry,
        address _settlementToken
    ) Ownable(initialOwner) {
        globalRegistry = _globalRegistry;
        settlementToken = IERC20(_settlementToken);
        emergencyMode = false;

        // HIDDEN: JPM Coin and Canton disabled by default
        jpmCoinEnabled = false;
        cantonEnabled = false;
    }

    // ============================================================
    // CIRCUIT BREAKER
    // ============================================================

    function emergencyPause() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = true;
        _pause();
        emit EmergencyModeActivated(msg.sender, block.timestamp);
    }

    function deactivateEmergency() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = false;
        _unpause();
    }

    // ============================================================
    // HIDDEN PIVOT ACTIVATION
    // ============================================================

    /**
     * @notice Activate JPM Coin settlement rails
     * @dev STRATEGIC: Enables institutional banking pivot in < 48 hours
     */
    function activateJPMCoinRails() external nonReentrant onlyPrimaryAdmin {
        jpmCoinEnabled = true;
    }

    /**
     * @notice Activate Canton Network integration
     * @dev STRATEGIC: Enables Digital Asset settlement
     */
    function activateCantonNetwork() external nonReentrant onlyPrimaryAdmin {
        cantonEnabled = true;
    }

    // ============================================================
    // ENTITY ONBOARDING - KYC/AML
    // ============================================================

    /**
     * @notice Onboard institutional entity with full KYC
     */
    function onboardEntity(
        string calldata legalName,
        string calldata lei,
        string calldata jurisdiction,
        KYCTier kycTier,
        address treasuryAddress,
        bytes32 kycDocumentHash,
        bytes32 amlScreeningHash
    ) 
        external 
        nonReentrant 
        onlyOwner 
        whenNotPaused 
        notInEmergency 
        returns (uint256 entityId) 
    {
        // CEI Pattern: Checks
        require(bytes(legalName).length > 0, "BankingAdapter: empty name");
        require(bytes(lei).length == 20, "BankingAdapter: invalid LEI");
        require(treasuryAddress != address(0), "BankingAdapter: zero treasury");
        require(leiToEntityId[lei] == 0, "BankingAdapter: LEI exists");

        // CEI Pattern: Effects
        entityId = _entityIdCounter++;

        entities[entityId] = InstitutionalEntity({
            entityId: entityId,
            legalName: legalName,
            lei: lei,
            jurisdiction: jurisdiction,
            kycTier: kycTier,
            riskLevel: AMLRiskLevel.LOW,
            treasuryAddress: treasuryAddress,
            kycDocumentHash: kycDocumentHash,
            amlScreeningHash: amlScreeningHash,
            onboardingDate: block.timestamp,
            lastReviewDate: block.timestamp,
            isActive: true,
            isPrimeBrokerage: kycTier == KYCTier.PRIME_BROKERAGE
        });

        addressToEntityId[treasuryAddress] = entityId;
        leiToEntityId[lei] = entityId;

        // CEI Pattern: Interactions
        emit EntityOnboarded(entityId, legalName, lei, kycTier);

        return entityId;
    }

    // ============================================================
    // TRANSACTION PROCESSING - AML COMPLIANCE
    // ============================================================

    /**
     * @notice Process institutional transaction with AML screening
     */
    function processTransaction(
        uint256 receiverEntityId,
        TransactionType txType,
        SettlementNetwork network,
        uint256 amount,
        bytes32 travelRuleHash
    ) 
        external 
        nonReentrant 
        onlyInstitutionalEntity 
        whenNotPaused 
        notInEmergency 
        notSanctioned(msg.sender) 
        returns (uint256 txId) 
    {
        // CEI Pattern: Checks
        uint256 senderEntityId = addressToEntityId[msg.sender];
        require(entities[receiverEntityId].isActive, "BankingAdapter: receiver not active");
        require(amount > 0, "BankingAdapter: zero amount");

        // AML threshold check
        bool amlFlag = amount >= AML_THRESHOLD_USD;

        // CEI Pattern: Effects
        txId = _txIdCounter++;

        uint256 fee = (amount * INSTITUTIONAL_FEE_BPS) / BPS_DENOMINATOR;

        bytes32 complianceHash = keccak256(abi.encodePacked(
            "INSTITUTIONAL_TX_V3",
            txId,
            senderEntityId,
            receiverEntityId,
            amount,
            block.timestamp,
            block.chainid
        ));

        transactions[txId] = InstitutionalTransaction({
            txId: txId,
            senderEntityId: senderEntityId,
            receiverEntityId: receiverEntityId,
            txType: txType,
            network: network,
            tokenAddress: address(settlementToken),
            amount: amount,
            fee: fee,
            complianceHash: complianceHash,
            travelRuleHash: travelRuleHash,
            timestamp: block.timestamp,
            amlFlagged: amlFlag,
            sanctionsCleared: true
        });

        entityTransactions[senderEntityId].push(txId);
        entityTransactions[receiverEntityId].push(txId);

        // CEI Pattern: Interactions
        if (amlFlag) {
            emit AMLFlagTriggered(txId, senderEntityId, "THRESHOLD_EXCEEDED", block.timestamp);
        }

        // Transfer tokens
        address receiverTreasury = entities[receiverEntityId].treasuryAddress;
        settlementToken.safeTransferFrom(msg.sender, receiverTreasury, amount - fee);
        settlementToken.safeTransferFrom(msg.sender, owner(), fee);

        emit TransactionProcessed(txId, senderEntityId, receiverEntityId, amount, network);

        return txId;
    }

    // ============================================================
    // HIDDEN: JPM COIN SETTLEMENT INTERFACE
    // ============================================================

    /**
     * @notice Initiate JPM Coin settlement (HIDDEN FEATURE)
     * @dev Only available when jpmCoinEnabled = true
     */
    function initiateJPMCoinSettlement(
        bytes32 jpmReferenceId,
        uint256 toEntityId,
        uint256 usdAmount,
        bytes32 nostroHash,
        bytes32 vostroHash,
        bool isIntraday
    ) 
        external 
        nonReentrant 
        onlyInstitutionalEntity 
        whenNotPaused 
        notInEmergency 
        returns (uint256 settlementId) 
    {
        // CEI Pattern: Checks
        require(jpmCoinEnabled, "BankingAdapter: JPM Coin not enabled");
        require(entities[toEntityId].isPrimeBrokerage, "BankingAdapter: receiver not prime brokerage");

        uint256 fromEntityId = addressToEntityId[msg.sender];

        // CEI Pattern: Effects
        settlementId = _settlementIdCounter++;

        _jpmSettlements[settlementId] = JPMCoinSettlement({
            settlementId: settlementId,
            jpmReferenceId: jpmReferenceId,
            fromEntityId: fromEntityId,
            toEntityId: toEntityId,
            usdAmount: usdAmount,
            jpmCoinAmount: usdAmount,  // 1:1 with USD
            nostroHash: nostroHash,
            vostroHash: vostroHash,
            settlementTime: block.timestamp,
            isIntraday: isIntraday,
            isCompleted: false
        });

        _jpmSettlementIds.push(settlementId);

        // CEI Pattern: Interactions
        emit JPMCoinSettlementInitiated(settlementId, jpmReferenceId, usdAmount);

        return settlementId;
    }

    /**
     * @notice Complete JPM Coin settlement
     */
    function completeJPMCoinSettlement(uint256 settlementId) 
        external 
        nonReentrant 
        onlyPrimaryAdmin 
    {
        require(jpmCoinEnabled, "BankingAdapter: JPM Coin not enabled");
        require(!_jpmSettlements[settlementId].isCompleted, "BankingAdapter: already completed");

        _jpmSettlements[settlementId].isCompleted = true;
    }

    // ============================================================
    // HIDDEN: CANTON NETWORK HANDSHAKE
    // ============================================================

    /**
     * @notice Initiate Canton Network handshake (HIDDEN FEATURE)
     * @dev Only available when cantonEnabled = true
     */
    function initiateCantonHandshake(
        bytes32 cantonPartyId,
        bytes32 workflowId,
        bytes32 contractTemplateHash
    ) 
        external 
        nonReentrant 
        onlyInstitutionalEntity 
        whenNotPaused 
        notInEmergency 
        returns (uint256 handshakeId) 
    {
        // CEI Pattern: Checks
        require(cantonEnabled, "BankingAdapter: Canton not enabled");

        // CEI Pattern: Effects
        handshakeId = _handshakeIdCounter++;

        _cantonHandshakes[handshakeId] = CantonHandshake({
            handshakeId: handshakeId,
            cantonPartyId: cantonPartyId,
            workflowId: workflowId,
            contractTemplateHash: contractTemplateHash,
            initiatedAt: block.timestamp,
            completedAt: 0,
            isConfirmed: false
        });

        _cantonHandshakeIds.push(handshakeId);

        return handshakeId;
    }

    /**
     * @notice Confirm Canton handshake
     */
    function confirmCantonHandshake(uint256 handshakeId) 
        external 
        nonReentrant 
        onlyPrimaryAdmin 
    {
        require(cantonEnabled, "BankingAdapter: Canton not enabled");
        require(!_cantonHandshakes[handshakeId].isConfirmed, "BankingAdapter: already confirmed");

        _cantonHandshakes[handshakeId].isConfirmed = true;
        _cantonHandshakes[handshakeId].completedAt = block.timestamp;

        emit CantonHandshakeCompleted(
            handshakeId,
            _cantonHandshakes[handshakeId].cantonPartyId,
            _cantonHandshakes[handshakeId].workflowId
        );
    }

    // ============================================================
    // TRADE FINANCE - LETTERS OF CREDIT
    // ============================================================

    /**
     * @notice Issue Letter of Credit
     */
    function issueLetterOfCredit(
        uint256 beneficiaryEntityId,
        uint256 applicantEntityId,
        uint256 amount,
        string calldata currency,
        bytes32 termsHash,
        bytes32 documentsHash,
        uint256 expiryDate
    ) 
        external 
        nonReentrant 
        onlyInstitutionalEntity 
        whenNotPaused 
        notInEmergency 
        returns (uint256 locId) 
    {
        // CEI Pattern: Checks
        uint256 issuingBankEntityId = addressToEntityId[msg.sender];
        require(entities[issuingBankEntityId].isPrimeBrokerage, "BankingAdapter: not authorized issuer");
        require(entities[beneficiaryEntityId].isActive, "BankingAdapter: beneficiary not active");
        require(expiryDate > block.timestamp, "BankingAdapter: invalid expiry");

        // CEI Pattern: Effects
        locId = _locIdCounter++;

        lettersOfCredit[locId] = LetterOfCredit({
            locId: locId,
            issuingBankEntityId: issuingBankEntityId,
            beneficiaryEntityId: beneficiaryEntityId,
            applicantEntityId: applicantEntityId,
            amount: amount,
            currency: currency,
            termsHash: termsHash,
            documentsHash: documentsHash,
            issuanceDate: block.timestamp,
            expiryDate: expiryDate,
            isConfirmed: false,
            isDrawn: false
        });

        // CEI Pattern: Interactions
        emit LetterOfCreditIssued(locId, issuingBankEntityId, amount);

        return locId;
    }

    // ============================================================
    // AML MANAGEMENT
    // ============================================================

    /**
     * @notice Flag entity for AML review
     */
    function flagEntityForAML(
        address entity,
        AMLRiskLevel riskLevel
    ) external nonReentrant onlyOwner {
        amlFlagged[entity] = riskLevel >= AMLRiskLevel.HIGH;
        entityRiskLevel[entity] = riskLevel;
    }

    /**
     * @notice Clear AML flag after review
     */
    function clearAMLFlag(address entity) external nonReentrant onlyOwner {
        amlFlagged[entity] = false;
        entityRiskLevel[entity] = AMLRiskLevel.LOW;
    }

    /**
     * @notice Add entity to sanctions list
     */
    function addToSanctionsList(bytes32 entityHash) external nonReentrant onlyOwner {
        sanctionedEntityHashes[entityHash] = true;
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    function getEntity(uint256 entityId) external view returns (InstitutionalEntity memory) {
        return entities[entityId];
    }

    function getTransaction(uint256 txId) external view returns (InstitutionalTransaction memory) {
        return transactions[txId];
    }

    function getEntityTransactions(uint256 entityId) external view returns (uint256[] memory) {
        return entityTransactions[entityId];
    }

    function getLetterOfCredit(uint256 locId) external view returns (LetterOfCredit memory) {
        return lettersOfCredit[locId];
    }

    function getTotalEntities() external view returns (uint256) {
        return _entityIdCounter;
    }

    function getTotalTransactions() external view returns (uint256) {
        return _txIdCounter;
    }

    // HIDDEN: Only accessible when features enabled
    function getJPMCoinSettlement(uint256 settlementId) 
        external 
        view 
        returns (JPMCoinSettlement memory) 
    {
        require(jpmCoinEnabled, "BankingAdapter: JPM Coin not enabled");
        return _jpmSettlements[settlementId];
    }

    function getCantonHandshake(uint256 handshakeId) 
        external 
        view 
        returns (CantonHandshake memory) 
    {
        require(cantonEnabled, "BankingAdapter: Canton not enabled");
        return _cantonHandshakes[handshakeId];
    }

    function isJPMCoinEnabled() external view returns (bool) {
        return jpmCoinEnabled;
    }

    function isCantonEnabled() external view returns (bool) {
        return cantonEnabled;
    }
}

contracts/adapters/MedicalDataAdapter.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title MedicalDataAdapter
 * @author PolarUniversal Team
 * @notice Medical Data Compliance Adapter - HIPAA/HITECH Compliant
 * @dev v3.1.0-Whale: Cross-Sector Adapter Stub
 * 
 * REGULATORY FRAMEWORK:
 * - HIPAA (Health Insurance Portability and Accountability Act)
 * - HITECH (Health Information Technology for Economic and Clinical Health)
 * - HL7 FHIR Standard Compatibility
 * - Patient Consent Management
 * 
 * STUB: Core structure implemented, ready for sector-specific expansion
 */
contract MedicalDataAdapter is Ownable2Step, ReentrancyGuard, Pausable {

    string public constant VERSION = "3.1.0-WHALE";
    string public constant ADAPTER_NAME = "MedicalDataAdapter";
    string public constant REGULATORY_FRAMEWORK = "HIPAA_HITECH_FHIR";

    address public constant PRIMARY_ADMIN = 0x9d91fC37529BD0c6D020dFf6519ee699C7e0A783;
    address public globalRegistry;
    bool public emergencyMode;

    // ============================================================
    // STRUCTS - HIPAA COMPLIANT
    // ============================================================

    struct PatientRecord {
        uint256 recordId;
        bytes32 patientIdHash;          // De-identified patient ID
        bytes32 medicalDataHash;        // Encrypted medical data hash
        bytes32 consentHash;            // Patient consent record
        address provider;
        uint256 createdAt;
        uint256 lastAccessedAt;
        bool isActive;
    }

    struct ConsentRecord {
        uint256 consentId;
        bytes32 patientIdHash;
        address authorizedProvider;
        uint256 grantedAt;
        uint256 expiresAt;
        bool isRevoked;
    }

    // ============================================================
    // STATE VARIABLES
    // ============================================================

    uint256 private _recordIdCounter;
    uint256 private _consentIdCounter;

    mapping(uint256 => PatientRecord) public patientRecords;
    mapping(bytes32 => uint256[]) public patientRecordsByHash;
    mapping(uint256 => ConsentRecord) public consents;
    mapping(address => bool) public authorizedProviders;

    // ============================================================
    // EVENTS
    // ============================================================

    event PatientRecordCreated(
        uint256 indexed recordId,
        bytes32 indexed patientIdHash,
        address indexed provider
    );

    event ConsentGranted(
        uint256 indexed consentId,
        bytes32 indexed patientIdHash,
        address indexed provider
    );

    event ConsentRevoked(
        uint256 indexed consentId,
        bytes32 indexed patientIdHash
    );

    event EmergencyModeActivated(address indexed admin, uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyPrimaryAdmin() {
        require(msg.sender == PRIMARY_ADMIN, "MedicalAdapter: not primary admin");
        _;
    }

    modifier onlyAuthorizedProvider() {
        require(authorizedProviders[msg.sender], "MedicalAdapter: not authorized");
        _;
    }

    modifier notInEmergency() {
        require(!emergencyMode, "MedicalAdapter: emergency mode");
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(
        address initialOwner,
        address _globalRegistry
    ) Ownable(initialOwner) {
        globalRegistry = _globalRegistry;
        emergencyMode = false;
        authorizedProviders[PRIMARY_ADMIN] = true;
    }

    // ============================================================
    // CIRCUIT BREAKER
    // ============================================================

    function emergencyPause() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = true;
        _pause();
        emit EmergencyModeActivated(msg.sender, block.timestamp);
    }

    function deactivateEmergency() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = false;
        _unpause();
    }

    // ============================================================
    // CORE FUNCTIONS - STUB IMPLEMENTATION
    // ============================================================

    /**
     * @notice Create patient record (HIPAA compliant)
     */
    function createPatientRecord(
        bytes32 patientIdHash,
        bytes32 medicalDataHash,
        bytes32 consentHash
    ) 
        external 
        nonReentrant 
        onlyAuthorizedProvider 
        whenNotPaused 
        notInEmergency 
        returns (uint256 recordId) 
    {
        recordId = _recordIdCounter++;

        patientRecords[recordId] = PatientRecord({
            recordId: recordId,
            patientIdHash: patientIdHash,
            medicalDataHash: medicalDataHash,
            consentHash: consentHash,
            provider: msg.sender,
            createdAt: block.timestamp,
            lastAccessedAt: block.timestamp,
            isActive: true
        });

        patientRecordsByHash[patientIdHash].push(recordId);

        emit PatientRecordCreated(recordId, patientIdHash, msg.sender);

        return recordId;
    }

    /**
     * @notice Grant consent for data access
     */
    function grantConsent(
        bytes32 patientIdHash,
        address authorizedProvider,
        uint256 validityPeriod
    ) 
        external 
        nonReentrant 
        whenNotPaused 
        notInEmergency 
        returns (uint256 consentId) 
    {
        consentId = _consentIdCounter++;

        consents[consentId] = ConsentRecord({
            consentId: consentId,
            patientIdHash: patientIdHash,
            authorizedProvider: authorizedProvider,
            grantedAt: block.timestamp,
            expiresAt: block.timestamp + validityPeriod,
            isRevoked: false
        });

        emit ConsentGranted(consentId, patientIdHash, authorizedProvider);

        return consentId;
    }

    /**
     * @notice Revoke consent
     */
    function revokeConsent(uint256 consentId) 
        external 
        nonReentrant 
        whenNotPaused 
    {
        require(!consents[consentId].isRevoked, "MedicalAdapter: already revoked");

        consents[consentId].isRevoked = true;

        emit ConsentRevoked(consentId, consents[consentId].patientIdHash);
    }

    /**
     * @notice Authorize healthcare provider
     */
    function authorizeProvider(address provider) external nonReentrant onlyOwner {
        authorizedProviders[provider] = true;
    }

    /**
     * @notice Revoke provider authorization
     */
    function revokeProvider(address provider) external nonReentrant onlyOwner {
        authorizedProviders[provider] = false;
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    function getPatientRecord(uint256 recordId) external view returns (PatientRecord memory) {
        return patientRecords[recordId];
    }

    function getConsent(uint256 consentId) external view returns (ConsentRecord memory) {
        return consents[consentId];
    }

    function getPatientRecordsByHash(bytes32 patientIdHash) external view returns (uint256[] memory) {
        return patientRecordsByHash[patientIdHash];
    }

    function getTotalRecords() external view returns (uint256) {
        return _recordIdCounter;
    }

    function isProviderAuthorized(address provider) external view returns (bool) {
        return authorizedProviders[provider];
    }
}

contracts/adapters/PharmaAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title PharmaAdapter
 * @author PolarUniversal Team
 * @notice Pharmaceutical Compliance Adapter - FDA-21-CFR-11 Compliant
 * @dev v3.1.0-Whale: Front-Facing Sector Adapter
 * 
 * REGULATORY FRAMEWORK:
 * ┌─────────────────────────────────────────────────────────────┐
 * │                    PHARMA ADAPTER                            │
 * │              FDA-21-CFR-11 Compliance                        │
 * ├─────────────────────────────────────────────────────────────┤
 * │                                                              │
 * │  ┌─────────────┐  ┌─────────────┐  ┌─────────────┐          │
 * │  │   BATCH     │  │   SUPPLY    │  │   AUDIT     │          │
 * │  │  TRACKING   │  │   CHAIN     │  │   TRAIL     │          │
 * │  └─────────────┘  └─────────────┘  └─────────────┘          │
 * │         │                │                │                  │
 * │         └────────────────┼────────────────┘                  │
 * │                          ▼                                   │
 * │              ┌─────────────────────┐                         │
 * │              │  GlobalCompliance   │                         │
 * │              │     Registry        │                         │
 * │              │    (Truth Layer)    │                         │
 * │              └─────────────────────┘                         │
 * │                                                              │
 * └─────────────────────────────────────────────────────────────┘
 * 
 * COMPLIANCE: FDA-21-CFR-11 (Electronic Records, Electronic Signatures)
 * SECURITY: OpenZeppelin v6 | Ownable2Step | ReentrancyGuard | CEI Pattern
 */
contract PharmaAdapter is Ownable2Step, ReentrancyGuard, Pausable {

    // ============================================================
    // CONSTANTS
    // ============================================================

    string public constant VERSION = "3.1.0-WHALE";
    string public constant ADAPTER_NAME = "PharmaAdapter";
    string public constant REGULATORY_FRAMEWORK = "FDA-21-CFR-11";

    address public constant PRIMARY_ADMIN = 0x9d91fC37529BD0c6D020dFf6519ee699C7e0A783;

    // ============================================================
    // ENUMS
    // ============================================================

    enum BatchStatus {
        MANUFACTURED,
        QUALITY_CHECKED,
        APPROVED,
        IN_TRANSIT,
        DELIVERED,
        RECALLED
    }

    enum AuditType {
        MANUFACTURING,
        QUALITY_CONTROL,
        SUPPLY_CHAIN,
        DISTRIBUTION,
        ADVERSE_EVENT
    }

    // ============================================================
    // STRUCTS - FDA-21-CFR-11 COMPLIANT
    // ============================================================

    struct DrugBatch {
        uint256 batchId;
        string drugName;
        string ndc;                    // National Drug Code
        string lotNumber;
        uint256 manufactureDate;
        uint256 expirationDate;
        address manufacturer;
        bytes32 formulaHash;           // Proprietary formula hash
        bytes32 qualityHash;           // QC test results hash
        BatchStatus status;
        bool isRecalled;
    }

    struct SupplyChainEvent {
        uint256 eventId;
        uint256 batchId;
        string eventType;
        address actor;
        string location;
        bytes32 temperatureHash;       // Cold-chain compliance
        bytes32 handlingHash;          // Handling certification
        uint256 timestamp;
        bytes32 signatureHash;         // Electronic signature (21-CFR-11)
    }

    struct AuditRecord {
        uint256 auditId;
        uint256 batchId;
        AuditType auditType;
        address auditor;
        bytes32 findingsHash;
        bytes32 correctiveActionsHash;
        uint256 timestamp;
        bool requiresFollowup;
        uint256 registryRecordId;      // Link to GlobalComplianceRegistry
    }

    struct ElectronicSignature {
        address signer;
        bytes32 signatureHash;
        string signerRole;
        string signerCredentials;
        uint256 timestamp;
        bool isValid;
    }

    // ============================================================
    // STATE VARIABLES
    // ============================================================

    uint256 private _batchIdCounter;
    uint256 private _eventIdCounter;
    uint256 private _auditIdCounter;

    address public globalRegistry;
    bool public emergencyMode;

    // Batch storage
    mapping(uint256 => DrugBatch) public batches;
    mapping(string => uint256) public lotToBatchId;
    mapping(address => uint256[]) public manufacturerBatches;

    // Supply chain events
    mapping(uint256 => SupplyChainEvent[]) public batchEvents;

    // Audit records
    mapping(uint256 => AuditRecord[]) public batchAudits;

    // Electronic signatures (21-CFR-11)
    mapping(bytes32 => ElectronicSignature) public signatures;
    mapping(address => bool) public authorizedSigners;

    // ============================================================
    // EVENTS
    // ============================================================

    event BatchRegistered(
        uint256 indexed batchId,
        string indexed drugName,
        string lotNumber,
        address indexed manufacturer
    );

    event BatchStatusUpdated(
        uint256 indexed batchId,
        BatchStatus oldStatus,
        BatchStatus newStatus,
        address updatedBy
    );

    event SupplyChainEventRecorded(
        uint256 indexed eventId,
        uint256 indexed batchId,
        string eventType,
        address indexed actor
    );

    event AuditRecorded(
        uint256 indexed auditId,
        uint256 indexed batchId,
        AuditType auditType,
        address indexed auditor
    );

    event ElectronicSignatureCreated(
        bytes32 indexed signatureHash,
        address indexed signer,
        uint256 timestamp
    );

    event BatchRecalled(
        uint256 indexed batchId,
        string reason,
        address recalledBy
    );

    event EmergencyModeActivated(address indexed admin, uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyPrimaryAdmin() {
        require(msg.sender == PRIMARY_ADMIN, "PharmaAdapter: not primary admin");
        _;
    }

    modifier onlyAuthorizedSigner() {
        require(authorizedSigners[msg.sender], "PharmaAdapter: not authorized signer");
        _;
    }

    modifier notInEmergency() {
        require(!emergencyMode, "PharmaAdapter: emergency mode");
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(
        address initialOwner,
        address _globalRegistry
    ) Ownable(initialOwner) {
        globalRegistry = _globalRegistry;
        emergencyMode = false;

        // Authorize primary admin as signer
        authorizedSigners[PRIMARY_ADMIN] = true;
    }

    // ============================================================
    // CIRCUIT BREAKER
    // ============================================================

    function emergencyPause() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = true;
        _pause();
        emit EmergencyModeActivated(msg.sender, block.timestamp);
    }

    function deactivateEmergency() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = false;
        _unpause();
    }

    // ============================================================
    // BATCH TRACKING - FDA-21-CFR-11
    // ============================================================

    /**
     * @notice Register a new drug batch
     * @param drugName Name of the pharmaceutical
     * @param ndc National Drug Code
     * @param lotNumber Lot/batch number
     * @param expirationDate Expiration timestamp
     * @param formulaHash Hash of proprietary formula
     */
    function registerBatch(
        string calldata drugName,
        string calldata ndc,
        string calldata lotNumber,
        uint256 expirationDate,
        bytes32 formulaHash
    ) 
        external 
        nonReentrant 
        whenNotPaused 
        notInEmergency 
        returns (uint256 batchId) 
    {
        // CEI Pattern: Checks
        require(bytes(drugName).length > 0, "PharmaAdapter: empty drug name");
        require(bytes(lotNumber).length > 0, "PharmaAdapter: empty lot number");
        require(lotToBatchId[lotNumber] == 0, "PharmaAdapter: lot exists");
        require(expirationDate > block.timestamp, "PharmaAdapter: invalid expiration");

        // CEI Pattern: Effects
        batchId = _batchIdCounter++;

        batches[batchId] = DrugBatch({
            batchId: batchId,
            drugName: drugName,
            ndc: ndc,
            lotNumber: lotNumber,
            manufactureDate: block.timestamp,
            expirationDate: expirationDate,
            manufacturer: msg.sender,
            formulaHash: formulaHash,
            qualityHash: bytes32(0),
            status: BatchStatus.MANUFACTURED,
            isRecalled: false
        });

        lotToBatchId[lotNumber] = batchId;
        manufacturerBatches[msg.sender].push(batchId);

        // CEI Pattern: Interactions
        emit BatchRegistered(batchId, drugName, lotNumber, msg.sender);

        return batchId;
    }

    /**
     * @notice Update batch status through supply chain
     */
    function updateBatchStatus(
        uint256 batchId,
        BatchStatus newStatus,
        bytes32 signatureHash
    ) 
        external 
        nonReentrant 
        onlyAuthorizedSigner 
        whenNotPaused 
        notInEmergency 
    {
        // CEI Pattern: Checks
        require(batches[batchId].batchId == batchId, "PharmaAdapter: batch not found");
        require(!batches[batchId].isRecalled, "PharmaAdapter: batch recalled");
        require(signatures[signatureHash].isValid, "PharmaAdapter: invalid signature");

        // CEI Pattern: Effects
        BatchStatus oldStatus = batches[batchId].status;
        batches[batchId].status = newStatus;

        // CEI Pattern: Interactions
        emit BatchStatusUpdated(batchId, oldStatus, newStatus, msg.sender);
    }

    /**
     * @notice Record supply chain event with cold-chain compliance
     */
    function recordSupplyChainEvent(
        uint256 batchId,
        string calldata eventType,
        string calldata location,
        bytes32 temperatureHash,
        bytes32 handlingHash,
        bytes32 signatureHash
    ) 
        external 
        nonReentrant 
        onlyAuthorizedSigner 
        whenNotPaused 
        notInEmergency 
        returns (uint256 eventId) 
    {
        // CEI Pattern: Checks
        require(batches[batchId].batchId == batchId, "PharmaAdapter: batch not found");
        require(!batches[batchId].isRecalled, "PharmaAdapter: batch recalled");

        // CEI Pattern: Effects
        eventId = _eventIdCounter++;

        SupplyChainEvent memory newEvent = SupplyChainEvent({
            eventId: eventId,
            batchId: batchId,
            eventType: eventType,
            actor: msg.sender,
            location: location,
            temperatureHash: temperatureHash,
            handlingHash: handlingHash,
            timestamp: block.timestamp,
            signatureHash: signatureHash
        });

        batchEvents[batchId].push(newEvent);

        // CEI Pattern: Interactions
        emit SupplyChainEventRecorded(eventId, batchId, eventType, msg.sender);

        return eventId;
    }

    /**
     * @notice Record audit with link to GlobalComplianceRegistry
     */
    function recordAudit(
        uint256 batchId,
        AuditType auditType,
        bytes32 findingsHash,
        bytes32 correctiveActionsHash,
        bool requiresFollowup
    ) 
        external 
        nonReentrant 
        whenNotPaused 
        notInEmergency 
        returns (uint256 auditId) 
    {
        // CEI Pattern: Checks
        require(batches[batchId].batchId == batchId, "PharmaAdapter: batch not found");

        // CEI Pattern: Effects
        auditId = _auditIdCounter++;

        AuditRecord memory newAudit = AuditRecord({
            auditId: auditId,
            batchId: batchId,
            auditType: auditType,
            auditor: msg.sender,
            findingsHash: findingsHash,
            correctiveActionsHash: correctiveActionsHash,
            timestamp: block.timestamp,
            requiresFollowup: requiresFollowup,
            registryRecordId: 0  // Set after registry call
        });

        batchAudits[batchId].push(newAudit);

        // CEI Pattern: Interactions
        emit AuditRecorded(auditId, batchId, auditType, msg.sender);

        return auditId;
    }

    // ============================================================
    // ELECTRONIC SIGNATURES - 21-CFR-11 COMPLIANT
    // ============================================================

    /**
     * @notice Create electronic signature (21-CFR-11)
     */
    function createElectronicSignature(
        bytes32 documentHash,
        string calldata signerRole,
        string calldata signerCredentials
    ) 
        external 
        nonReentrant 
        onlyAuthorizedSigner 
        returns (bytes32 signatureHash) 
    {
        // CEI Pattern: Effects
        signatureHash = keccak256(abi.encodePacked(
            "FDA-21-CFR-11-SIGNATURE",
            msg.sender,
            documentHash,
            signerRole,
            block.timestamp,
            block.chainid
        ));

        signatures[signatureHash] = ElectronicSignature({
            signer: msg.sender,
            signatureHash: signatureHash,
            signerRole: signerRole,
            signerCredentials: signerCredentials,
            timestamp: block.timestamp,
            isValid: true
        });

        // CEI Pattern: Interactions
        emit ElectronicSignatureCreated(signatureHash, msg.sender, block.timestamp);

        return signatureHash;
    }

    /**
     * @notice Authorize a new signer
     */
    function authorizeSigner(address signer) external nonReentrant onlyOwner {
        authorizedSigners[signer] = true;
    }

    /**
     * @notice Revoke signer authorization
     */
    function revokeSigner(address signer) external nonReentrant onlyOwner {
        authorizedSigners[signer] = false;
    }

    // ============================================================
    // RECALL MANAGEMENT
    // ============================================================

    /**
     * @notice Initiate batch recall
     */
    function recallBatch(
        uint256 batchId,
        string calldata reason
    ) 
        external 
        nonReentrant 
        onlyOwner 
    {
        // CEI Pattern: Checks
        require(batches[batchId].batchId == batchId, "PharmaAdapter: batch not found");
        require(!batches[batchId].isRecalled, "PharmaAdapter: already recalled");

        // CEI Pattern: Effects
        batches[batchId].isRecalled = true;
        batches[batchId].status = BatchStatus.RECALLED;

        // CEI Pattern: Interactions
        emit BatchRecalled(batchId, reason, msg.sender);
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    function getBatch(uint256 batchId) external view returns (DrugBatch memory) {
        return batches[batchId];
    }

    function getBatchEvents(uint256 batchId) external view returns (SupplyChainEvent[] memory) {
        return batchEvents[batchId];
    }

    function getBatchAudits(uint256 batchId) external view returns (AuditRecord[] memory) {
        return batchAudits[batchId];
    }

    function getManufacturerBatches(address manufacturer) external view returns (uint256[] memory) {
        return manufacturerBatches[manufacturer];
    }

    function getSignature(bytes32 signatureHash) external view returns (ElectronicSignature memory) {
        return signatures[signatureHash];
    }

    function getTotalBatches() external view returns (uint256) {
        return _batchIdCounter;
    }

    function isSignerAuthorized(address signer) external view returns (bool) {
        return authorizedSigners[signer];
    }
}

contracts/core/GlobalComplianceRegistry..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title GlobalComplianceRegistry
 * @author PolarUniversal Team
 * @notice The "Truth Layer" - Central registry for all compliance sectors
 * @dev v3.1.0-Whale: Modular Compliance OS Core Engine
 * 
 * ARCHITECTURE:
 * ┌─────────────────────────────────────────────────────────────┐
 * │                  GLOBAL COMPLIANCE REGISTRY                  │
 * │                    (Truth Layer - /core)                     │
 * ├─────────────────────────────────────────────────────────────┤
 * │  ┌─────────────┐  ┌─────────────┐  ┌─────────────┐          │
 * │  │   Pharma    │  │   Banking   │  │   Medical   │          │
 * │  │   Adapter   │  │   Adapter   │  │   Adapter   │          │
 * │  └──────┬──────┘  └──────┬──────┘  └──────┬──────┘          │
 * │         │                │                │                  │
 * │         └────────────────┼────────────────┘                  │
 * │                          ▼                                   │
 * │              ┌─────────────────────┐                         │
 * │              │  SwitchableProvider │                         │
 * │              │  (Monad ↔ Movement) │                         │
 * │              └─────────────────────┘                         │
 * └─────────────────────────────────────────────────────────────┘
 * 
 * SECURITY: OpenZeppelin v6 | Ownable2Step | ReentrancyGuard | CEI Pattern
 * UPTIME: 99.9% via Switchable Provider (Monad Primary, Movement Secondary)
 */
contract GlobalComplianceRegistry is Ownable2Step, ReentrancyGuard, Pausable {

    // ============================================================
    // CONSTANTS - INSTITUTIONAL CONFIGURATION
    // ============================================================

    string public constant VERSION = "3.1.0-WHALE";
    string public constant ARCHITECTURE = "MODULAR_COMPLIANCE_OS";

    address public constant PRIMARY_ADMIN = 0x9d91fC37529BD0c6D020dFf6519ee699C7e0A783;

    // ============================================================
    // SECTOR ENUMERATION - PLATFORM MULTIPLIER VALUE
    // ============================================================

    enum ComplianceSector {
        HEALTHCARE,      // HIPAA, FDA-21-CFR-11
        AI_AGENTS,       // Virtual Protocol, TAO
        DEPIN,           // Hardware attestation, IoT
        PAYMENTS,        // B2B settlements, USDC
        PRIVACY,         // Story Protocol, IP registry
        PHARMA,          // Batch tracking, supply chain
        BANKING,         // JPM Coin, Canton, AML (HIDDEN PIVOT)
        EDUCATION,       // Credential verification
        MEDICAL_DATA     // Patient records, consent
    }

    // ============================================================
    // STRUCTS - UNIVERSAL COMPLIANCE RECORD
    // ============================================================

    struct ComplianceRecord {
        uint256 recordId;
        ComplianceSector sector;
        address registrant;
        bytes32 dataHash;
        bytes32 regulatoryHash;
        uint256 timestamp;
        uint256 expirationTimestamp;
        bool isActive;
        bool isVerified;
        address verifier;
    }

    struct AdapterRegistration {
        address adapterAddress;
        ComplianceSector sector;
        string adapterName;
        string version;
        bool isActive;
        uint256 registeredAt;
        uint256 totalRecords;
    }

    struct ProviderStatus {
        string providerName;
        string rpcEndpoint;
        uint256 chainId;
        bool isPrimary;
        bool isActive;
        uint256 lastHealthCheck;
        uint256 latencyMs;
    }

    // ============================================================
    // STATE VARIABLES
    // ============================================================

    uint256 private _recordIdCounter;
    uint256 private _adapterIdCounter;

    bool public emergencyMode;

    // Record storage
    mapping(uint256 => ComplianceRecord) public records;
    mapping(address => uint256[]) public registrantRecords;
    mapping(ComplianceSector => uint256[]) public sectorRecords;

    // Adapter registry
    mapping(address => AdapterRegistration) public adapters;
    mapping(ComplianceSector => address) public sectorAdapter;
    address[] public registeredAdapters;

    // Provider configuration (Switchable)
    ProviderStatus public primaryProvider;
    ProviderStatus public secondaryProvider;
    bool public useSecondaryProvider;

    // ============================================================
    // EVENTS - INSTITUTIONAL TRANSPARENCY
    // ============================================================

    event ComplianceRecordCreated(
        uint256 indexed recordId,
        ComplianceSector indexed sector,
        address indexed registrant,
        bytes32 dataHash,
        uint256 timestamp
    );

    event ComplianceRecordVerified(
        uint256 indexed recordId,
        address indexed verifier,
        uint256 timestamp
    );

    event AdapterRegistered(
        address indexed adapterAddress,
        ComplianceSector indexed sector,
        string adapterName,
        string version
    );

    event AdapterDeactivated(
        address indexed adapterAddress,
        ComplianceSector indexed sector,
        uint256 timestamp
    );

    event ProviderSwitched(
        string fromProvider,
        string toProvider,
        uint256 timestamp,
        string reason
    );

    event EmergencyModeActivated(address indexed admin, uint256 timestamp);
    event EmergencyModeDeactivated(address indexed admin, uint256 timestamp);

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyPrimaryAdmin() {
        require(msg.sender == PRIMARY_ADMIN, "GlobalRegistry: not primary admin");
        _;
    }

    modifier onlyRegisteredAdapter() {
        require(adapters[msg.sender].isActive, "GlobalRegistry: not registered adapter");
        _;
    }

    modifier notInEmergency() {
        require(!emergencyMode, "GlobalRegistry: emergency mode");
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(address initialOwner) Ownable(initialOwner) {
        // CEI Pattern: Effects
        emergencyMode = false;

        // Initialize Switchable Provider (Monad Primary, Movement Secondary)
        primaryProvider = ProviderStatus({
            providerName: "Monad Mainnet",
            rpcEndpoint: "https://mainnet.monad.xyz",
            chainId: 41454,
            isPrimary: true,
            isActive: true,
            lastHealthCheck: block.timestamp,
            latencyMs: 50
        });

        secondaryProvider = ProviderStatus({
            providerName: "Movement Mainnet",
            rpcEndpoint: "https://mainnet.movementlabs.xyz",
            chainId: 30730,
            isPrimary: false,
            isActive: true,
            lastHealthCheck: block.timestamp,
            latencyMs: 100
        });

        useSecondaryProvider = false;
    }

    // ============================================================
    // CIRCUIT BREAKER - FORTRESS SECURITY
    // ============================================================

    function emergencyPause() external nonReentrant onlyPrimaryAdmin {
        // CEI Pattern: Effects
        emergencyMode = true;
        _pause();

        // CEI Pattern: Interactions
        emit EmergencyModeActivated(msg.sender, block.timestamp);
    }

    function deactivateEmergency() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = false;
        _unpause();
        emit EmergencyModeDeactivated(msg.sender, block.timestamp);
    }

    // ============================================================
    // SWITCHABLE PROVIDER - 99.9% UPTIME GUARANTEE
    // ============================================================

    /**
     * @notice Switch between Monad (Primary) and Movement (Secondary)
     * @dev Zero-Downtime architecture for institutional reliability
     */
    function switchProvider(string calldata reason) 
        external 
        nonReentrant 
        onlyOwner 
    {
        // CEI Pattern: Checks
        require(bytes(reason).length > 0, "GlobalRegistry: reason required");

        // CEI Pattern: Effects
        string memory fromProvider = useSecondaryProvider ? 
            secondaryProvider.providerName : 
            primaryProvider.providerName;

        useSecondaryProvider = !useSecondaryProvider;

        string memory toProvider = useSecondaryProvider ? 
            secondaryProvider.providerName : 
            primaryProvider.providerName;

        // CEI Pattern: Interactions
        emit ProviderSwitched(fromProvider, toProvider, block.timestamp, reason);
    }

    /**
     * @notice Update provider health check (called by monitoring)
     */
    function updateProviderHealth(
        bool isPrimary,
        uint256 latencyMs
    ) external nonReentrant onlyOwner {
        // CEI Pattern: Effects
        if (isPrimary) {
            primaryProvider.lastHealthCheck = block.timestamp;
            primaryProvider.latencyMs = latencyMs;
        } else {
            secondaryProvider.lastHealthCheck = block.timestamp;
            secondaryProvider.latencyMs = latencyMs;
        }
    }

    /**
     * @notice Auto-failover if primary latency exceeds threshold
     */
    function checkAutoFailover(uint256 latencyThresholdMs) 
        external 
        nonReentrant 
        onlyOwner 
        returns (bool switched) 
    {
        // CEI Pattern: Checks
        if (!useSecondaryProvider && primaryProvider.latencyMs > latencyThresholdMs) {
            // CEI Pattern: Effects
            useSecondaryProvider = true;
            switched = true;

            // CEI Pattern: Interactions
            emit ProviderSwitched(
                primaryProvider.providerName,
                secondaryProvider.providerName,
                block.timestamp,
                "AUTO_FAILOVER_LATENCY_EXCEEDED"
            );
        }
        return switched;
    }

    // ============================================================
    // ADAPTER REGISTRY - MODULAR ARCHITECTURE
    // ============================================================

    /**
     * @notice Register a sector adapter (e.g., PharmaAdapter, BankingAdapter)
     * @dev All adapters share this core Truth Layer
     */
    function registerAdapter(
        address adapterAddress,
        ComplianceSector sector,
        string calldata adapterName,
        string calldata version
    ) 
        external 
        nonReentrant 
        onlyOwner 
        whenNotPaused 
    {
        // CEI Pattern: Checks
        require(adapterAddress != address(0), "GlobalRegistry: zero adapter");
        require(bytes(adapterName).length > 0, "GlobalRegistry: empty name");
        require(!adapters[adapterAddress].isActive, "GlobalRegistry: already registered");

        // CEI Pattern: Effects
        adapters[adapterAddress] = AdapterRegistration({
            adapterAddress: adapterAddress,
            sector: sector,
            adapterName: adapterName,
            version: version,
            isActive: true,
            registeredAt: block.timestamp,
            totalRecords: 0
        });

        sectorAdapter[sector] = adapterAddress;
        registeredAdapters.push(adapterAddress);

        // CEI Pattern: Interactions
        emit AdapterRegistered(adapterAddress, sector, adapterName, version);
    }

    /**
     * @notice Deactivate an adapter (soft delete)
     */
    function deactivateAdapter(address adapterAddress) 
        external 
        nonReentrant 
        onlyOwner 
    {
        // CEI Pattern: Checks
        require(adapters[adapterAddress].isActive, "GlobalRegistry: not active");

        // CEI Pattern: Effects
        ComplianceSector sector = adapters[adapterAddress].sector;
        adapters[adapterAddress].isActive = false;
        sectorAdapter[sector] = address(0);

        // CEI Pattern: Interactions
        emit AdapterDeactivated(adapterAddress, sector, block.timestamp);
    }

    // ============================================================
    // COMPLIANCE RECORD MANAGEMENT - TRUTH LAYER
    // ============================================================

    /**
     * @notice Create a compliance record (called by adapters)
     * @dev This is the universal entry point for all sectors
     */
    function createComplianceRecord(
        ComplianceSector sector,
        address registrant,
        bytes32 dataHash,
        bytes32 regulatoryHash,
        uint256 validityPeriod
    ) 
        external 
        nonReentrant 
        onlyRegisteredAdapter 
        whenNotPaused 
        notInEmergency 
        returns (uint256 recordId) 
    {
        // CEI Pattern: Checks
        require(registrant != address(0), "GlobalRegistry: zero registrant");
        require(dataHash != bytes32(0), "GlobalRegistry: empty data hash");

        // CEI Pattern: Effects
        recordId = _recordIdCounter++;

        uint256 expiration = validityPeriod > 0 ? 
            block.timestamp + validityPeriod : 
            type(uint256).max;

        records[recordId] = ComplianceRecord({
            recordId: recordId,
            sector: sector,
            registrant: registrant,
            dataHash: dataHash,
            regulatoryHash: regulatoryHash,
            timestamp: block.timestamp,
            expirationTimestamp: expiration,
            isActive: true,
            isVerified: false,
            verifier: address(0)
        });

        registrantRecords[registrant].push(recordId);
        sectorRecords[sector].push(recordId);
        adapters[msg.sender].totalRecords++;

        // CEI Pattern: Interactions
        emit ComplianceRecordCreated(recordId, sector, registrant, dataHash, block.timestamp);

        return recordId;
    }

    /**
     * @notice Verify a compliance record (auditor function)
     */
    function verifyRecord(uint256 recordId) 
        external 
        nonReentrant 
        whenNotPaused 
        notInEmergency 
    {
        // CEI Pattern: Checks
        require(records[recordId].isActive, "GlobalRegistry: record not active");
        require(!records[recordId].isVerified, "GlobalRegistry: already verified");
        require(block.timestamp < records[recordId].expirationTimestamp, "GlobalRegistry: expired");

        // CEI Pattern: Effects
        records[recordId].isVerified = true;
        records[recordId].verifier = msg.sender;

        // CEI Pattern: Interactions
        emit ComplianceRecordVerified(recordId, msg.sender, block.timestamp);
    }

    /**
     * @notice Deactivate a compliance record
     */
    function deactivateRecord(uint256 recordId) 
        external 
        nonReentrant 
        onlyOwner 
    {
        // CEI Pattern: Checks
        require(records[recordId].isActive, "GlobalRegistry: not active");

        // CEI Pattern: Effects
        records[recordId].isActive = false;
    }

    // ============================================================
    // VIEW FUNCTIONS - TRANSPARENCY
    // ============================================================

    function getRecord(uint256 recordId) external view returns (ComplianceRecord memory) {
        return records[recordId];
    }

    function getRegistrantRecords(address registrant) external view returns (uint256[] memory) {
        return registrantRecords[registrant];
    }

    function getSectorRecords(ComplianceSector sector) external view returns (uint256[] memory) {
        return sectorRecords[sector];
    }

    function getAdapter(address adapterAddress) external view returns (AdapterRegistration memory) {
        return adapters[adapterAddress];
    }

    function getTotalRecords() external view returns (uint256) {
        return _recordIdCounter;
    }

    function getTotalAdapters() external view returns (uint256) {
        return registeredAdapters.length;
    }

    function getCurrentProvider() external view returns (ProviderStatus memory) {
        return useSecondaryProvider ? secondaryProvider : primaryProvider;
    }

    function isRecordValid(uint256 recordId) external view returns (bool) {
        ComplianceRecord memory record = records[recordId];
        return record.isActive && 
               record.isVerified && 
               block.timestamp < record.expirationTimestamp;
    }
}

