// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SwitchableProvider
 * @author PolarUniversal Team
 * @notice Multi-chain failover system for 99.9% uptime guarantee
 * @dev v3.1.0-Whale: Zero-Downtime Architecture
 * 
 * FAILOVER ARCHITECTURE:
 * ┌─────────────────────────────────────────────────────────┐
 * │                 SWITCHABLE PROVIDER                      │
 * ├─────────────────────────────────────────────────────────┤
 * │                                                          │
 * │    ┌──────────────────┐     ┌──────────────────┐        │
 * │    │  MONAD MAINNET   │     │ MOVEMENT MAINNET │        │
 * │    │   (PRIMARY)      │────▶│   (SECONDARY)    │        │
 * │    │   Chain: 41454   │     │   Chain: 30730   │        │
 * │    │   Latency: 50ms  │     │   Latency: 100ms │        │
 * │    └──────────────────┘     └──────────────────┘        │
 * │              │                       │                   │
 * │              └───────────┬───────────┘                   │
 * │                          ▼                               │
 * │              ┌──────────────────┐                        │
 * │              │  HEALTH MONITOR  │                        │
 * │              │  Auto-Failover   │                        │
 * │              │  < 200ms switch  │                        │
 * │              └──────────────────┘                        │
 * │                                                          │
 * └─────────────────────────────────────────────────────────┘
 * 
 * UPTIME GUARANTEE: 99.9% (< 8.76 hours downtime/year)
 * FAILOVER TIME: < 200ms automatic switch
 */
contract SwitchableProvider is Ownable2Step, ReentrancyGuard {

    // ============================================================
    // CONSTANTS
    // ============================================================

    string public constant VERSION = "3.1.0-WHALE";
    uint256 public constant MAX_LATENCY_THRESHOLD_MS = 500;
    uint256 public constant DEFAULT_HEALTH_CHECK_INTERVAL = 30; // seconds

    // ============================================================
    // STRUCTS
    // ============================================================

    struct Provider {
        uint256 providerId;
        string name;
        string rpcEndpoint;
        uint256 chainId;
        uint256 latencyMs;
        uint256 lastHealthCheck;
        uint256 failureCount;
        uint256 successCount;
        bool isActive;
        bool isPrimary;
    }

    struct HealthMetrics {
        uint256 totalRequests;
        uint256 successfulRequests;
        uint256 failedRequests;
        uint256 averageLatencyMs;
        uint256 lastDowntime;
        uint256 downtimeDurationSeconds;
    }

    struct FailoverEvent {
        uint256 eventId;
        uint256 fromProviderId;
        uint256 toProviderId;
        uint256 timestamp;
        string reason;
        bool wasAutomatic;
    }

    // ============================================================
    // STATE VARIABLES
    // ============================================================

    uint256 private _providerIdCounter;
    uint256 private _failoverEventCounter;
    uint256 public activeProviderId;
    uint256 public latencyThresholdMs;
    uint256 public healthCheckInterval;

    mapping(uint256 => Provider) public providers;
    mapping(uint256 => HealthMetrics) public providerHealth;
    mapping(uint256 => FailoverEvent) public failoverHistory;

    uint256[] public providerIds;

    // ============================================================
    // EVENTS
    // ============================================================

    event ProviderAdded(
        uint256 indexed providerId,
        string name,
        uint256 chainId,
        bool isPrimary
    );

    event ProviderHealthUpdated(
        uint256 indexed providerId,
        uint256 latencyMs,
        bool isHealthy
    );

    event FailoverExecuted(
        uint256 indexed eventId,
        uint256 indexed fromProviderId,
        uint256 indexed toProviderId,
        string reason,
        bool automatic
    );

    event LatencyThresholdUpdated(
        uint256 oldThreshold,
        uint256 newThreshold
    );

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(address initialOwner) Ownable(initialOwner) {
        latencyThresholdMs = 300; // 300ms default threshold
        healthCheckInterval = DEFAULT_HEALTH_CHECK_INTERVAL;

        // Initialize Monad as Primary
        _addProvider("Monad Mainnet", "https://mainnet.monad.xyz", 41454, true);

        // Initialize Movement as Secondary
        _addProvider("Movement Mainnet", "https://mainnet.movementlabs.xyz", 30730, false);

        // Set Monad as active
        activeProviderId = 0;
    }

    // ============================================================
    // PROVIDER MANAGEMENT
    // ============================================================

    function _addProvider(
        string memory name,
        string memory rpcEndpoint,
        uint256 chainId,
        bool isPrimary
    ) internal returns (uint256 providerId) {
        providerId = _providerIdCounter++;

        providers[providerId] = Provider({
            providerId: providerId,
            name: name,
            rpcEndpoint: rpcEndpoint,
            chainId: chainId,
            latencyMs: 0,
            lastHealthCheck: block.timestamp,
            failureCount: 0,
            successCount: 0,
            isActive: true,
            isPrimary: isPrimary
        });

        providerHealth[providerId] = HealthMetrics({
            totalRequests: 0,
            successfulRequests: 0,
            failedRequests: 0,
            averageLatencyMs: 0,
            lastDowntime: 0,
            downtimeDurationSeconds: 0
        });

        providerIds.push(providerId);

        emit ProviderAdded(providerId, name, chainId, isPrimary);

        return providerId;
    }

    /**
     * @notice Add a new provider to the failover pool
     */
    function addProvider(
        string calldata name,
        string calldata rpcEndpoint,
        uint256 chainId,
        bool isPrimary
    ) external nonReentrant onlyOwner returns (uint256) {
        return _addProvider(name, rpcEndpoint, chainId, isPrimary);
    }

    /**
     * @notice Update provider health metrics
     * @dev Called by off-chain monitoring service
     */
    function updateProviderHealth(
        uint256 providerId,
        uint256 latencyMs,
        bool success
    ) external nonReentrant onlyOwner {
        // CEI Pattern: Checks
        require(providers[providerId].isActive, "Provider: not active");

        // CEI Pattern: Effects
        Provider storage provider = providers[providerId];
        HealthMetrics storage health = providerHealth[providerId];

        provider.latencyMs = latencyMs;
        provider.lastHealthCheck = block.timestamp;
        health.totalRequests++;

        if (success) {
            provider.successCount++;
            health.successfulRequests++;
            provider.failureCount = 0; // Reset consecutive failures

            // Update average latency
            if (health.averageLatencyMs == 0) {
                health.averageLatencyMs = latencyMs;
            } else {
                health.averageLatencyMs = (health.averageLatencyMs + latencyMs) / 2;
            }
        } else {
            provider.failureCount++;
            health.failedRequests++;
        }

        // CEI Pattern: Interactions
        emit ProviderHealthUpdated(providerId, latencyMs, success);

        // Check if auto-failover needed
        if (providerId == activeProviderId && 
            (provider.failureCount >= 3 || latencyMs > latencyThresholdMs)) {
            _executeAutoFailover(providerId, "HEALTH_CHECK_FAILED");
        }
    }

    // ============================================================
    // FAILOVER LOGIC - ZERO-DOWNTIME
    // ============================================================

    /**
     * @notice Manual failover to specific provider
     */
    function manualFailover(
        uint256 toProviderId,
        string calldata reason
    ) external nonReentrant onlyOwner {
        // CEI Pattern: Checks
        require(providers[toProviderId].isActive, "Provider: target not active");
        require(toProviderId != activeProviderId, "Provider: already active");

        // CEI Pattern: Effects
        uint256 fromProviderId = activeProviderId;
        activeProviderId = toProviderId;

        uint256 eventId = _failoverEventCounter++;
        failoverHistory[eventId] = FailoverEvent({
            eventId: eventId,
            fromProviderId: fromProviderId,
            toProviderId: toProviderId,
            timestamp: block.timestamp,
            reason: reason,
            wasAutomatic: false
        });

        // CEI Pattern: Interactions
        emit FailoverExecuted(eventId, fromProviderId, toProviderId, reason, false);
    }

    /**
     * @notice Auto-failover to next healthy provider
     */
    function _executeAutoFailover(
        uint256 failedProviderId,
        string memory reason
    ) internal {
        // Find next healthy provider
        uint256 nextProviderId = _findHealthyProvider(failedProviderId);

        if (nextProviderId != failedProviderId) {
            // CEI Pattern: Effects
            uint256 fromProviderId = activeProviderId;
            activeProviderId = nextProviderId;

            // Record downtime
            providerHealth[failedProviderId].lastDowntime = block.timestamp;

            uint256 eventId = _failoverEventCounter++;
            failoverHistory[eventId] = FailoverEvent({
                eventId: eventId,
                fromProviderId: fromProviderId,
                toProviderId: nextProviderId,
                timestamp: block.timestamp,
                reason: reason,
                wasAutomatic: true
            });

            // CEI Pattern: Interactions
            emit FailoverExecuted(eventId, fromProviderId, nextProviderId, reason, true);
        }
    }

    /**
     * @notice Find next healthy provider
     */
    function _findHealthyProvider(uint256 excludeProviderId) internal view returns (uint256) {
        for (uint256 i = 0; i < providerIds.length; i++) {
            uint256 providerId = providerIds[i];
            Provider memory provider = providers[providerId];

            if (providerId != excludeProviderId && 
                provider.isActive && 
                provider.failureCount < 3 &&
                provider.latencyMs <= latencyThresholdMs) {
                return providerId;
            }
        }
        return excludeProviderId; // No healthy alternative found
    }

    // ============================================================
    // CONFIGURATION
    // ============================================================

    /**
     * @notice Update latency threshold for auto-failover
     */
    function setLatencyThreshold(uint256 newThresholdMs) external nonReentrant onlyOwner {
        require(newThresholdMs <= MAX_LATENCY_THRESHOLD_MS, "Provider: threshold too high");

        uint256 oldThreshold = latencyThresholdMs;
        latencyThresholdMs = newThresholdMs;

        emit LatencyThresholdUpdated(oldThreshold, newThresholdMs);
    }

    /**
     * @notice Deactivate a provider
     */
    function deactivateProvider(uint256 providerId) external nonReentrant onlyOwner {
        require(providers[providerId].isActive, "Provider: not active");
        require(providerId != activeProviderId, "Provider: cannot deactivate active");

        providers[providerId].isActive = false;
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    function getActiveProvider() external view returns (Provider memory) {
        return providers[activeProviderId];
    }

    function getProvider(uint256 providerId) external view returns (Provider memory) {
        return providers[providerId];
    }

    function getProviderHealth(uint256 providerId) external view returns (HealthMetrics memory) {
        return providerHealth[providerId];
    }

    function getFailoverEvent(uint256 eventId) external view returns (FailoverEvent memory) {
        return failoverHistory[eventId];
    }

    function getTotalProviders() external view returns (uint256) {
        return providerIds.length;
    }

    function getTotalFailovers() external view returns (uint256) {
        return _failoverEventCounter;
    }

    /**
     * @notice Calculate uptime percentage (basis points)
     */
    function getUptimePercentage(uint256 providerId) external view returns (uint256) {
        HealthMetrics memory health = providerHealth[providerId];
        if (health.totalRequests == 0) return 10000; // 100%

        return (health.successfulRequests * 10000) / health.totalRequests;
    }
}

contracts/solidity/AuditPayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

// ============================================================
// PAYMENTS SECTOR: Instant B2B Settlements
// ============================================================
// ECOSYSTEM INTEGRATIONS (Airdrop Multiplier Eligible):
// - $AERO (Aerodrome): Base L2 liquidity routing
// - $HYPE (Hyperliquid): Perps settlement integration
// - $ONDO (Ondo Finance): Yield-bearing treasury (USDY)
// - $USDC: Primary settlement token
// - $PYUSD: PayPal stablecoin support
// ============================================================
// Fortress Security: Ownable2Step, ReentrancyGuard, CEI Pattern
// ============================================================

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title AuditPayment - Payments Sector
 * @notice Instant B2B Settlements for Compliance Audits
 * @dev Fortress Security: Ownable2Step, SafeERC20, CEI Pattern
 * @dev Primary Admin: 0x9d91fC37529BD0c6D020dFf6519ee699C7e0A783
 * @dev Multi-Chain: Monad (Primary), Movement (Secondary)
 */
contract AuditPayment is Ownable2Step, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ============================================================
    // CONSTANTS
    // ============================================================

    address public constant PRIMARY_ADMIN = 0x9d91fC37529BD0c6D020dFf6519ee699C7e0A783;
    string public constant VERSION = "3.0.0-sovereign";

    uint256 public constant PLATFORM_FEE_BPS = 50;      // 0.5%
    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant MAX_BATCH_SIZE = 50;

    // ============================================================
    // STATE VARIABLES
    // ============================================================

    IERC20 public usdcToken;
    IERC20 public ondoUSDY;     // Yield-bearing treasury ($ONDO)

    uint256 private _paymentIdCounter;

    // Circuit Breaker
    bool public emergencyMode;

    // ============================================================
    // DATA STRUCTURES
    // ============================================================

    struct PaymentRecord {
        uint256 paymentId;
        uint256 auditRecordId;
        address payer;
        address payee;
        uint256 amount;
        uint256 platformFee;
        uint256 timestamp;
        PaymentStatus status;
        bytes32 settlementHash;
        PaymentRoute route;
    }

    enum PaymentStatus { PENDING, COMPLETED, REFUNDED, DISPUTED }
    enum PaymentRoute { DIRECT, AERO_ROUTED, HYPE_PERPS, ONDO_YIELD }

    // Mappings
    mapping(uint256 => PaymentRecord) public payments;
    mapping(address => uint256) public auditorEarnings;
    mapping(address => uint256) public platformFees;
    mapping(address => uint256) public treasuryYield;   // $ONDO yield tracking

    // ============================================================
    // EVENTS
    // ============================================================

    event InstantSettlement(
        uint256 indexed paymentId,
        uint256 indexed auditRecordId,
        address indexed payer,
        address payee,
        uint256 amount,
        bytes32 settlementHash,
        PaymentRoute route
    );

    event B2BPaymentCompleted(
        uint256 indexed paymentId,
        address indexed businessPayer,
        address indexed businessPayee,
        uint256 netAmount,
        uint256 fee
    );

    event YieldDeposited(
        address indexed depositor,
        uint256 amount,
        uint256 usdyShares
    );

    event EmergencyPauseActivated(
        address indexed activator,
        uint256 timestamp
    );

    event TokenUpdated(
        string tokenType,
        address indexed oldToken,
        address indexed newToken
    );

    // ============================================================
    // MODIFIERS
    // ============================================================

    modifier onlyPrimaryAdmin() {
        require(msg.sender == PRIMARY_ADMIN, "AuditPayment: not primary admin");
        _;
    }

    modifier notInEmergency() {
        require(!emergencyMode, "AuditPayment: emergency mode");
        _;
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    constructor(
        address initialOwner, 
        address _usdcToken,
        address _ondoUSDY
    ) Ownable(initialOwner) {
        // CEI Pattern: Checks
        require(_usdcToken != address(0), "AuditPayment: zero USDC");

        // CEI Pattern: Effects
        usdcToken = IERC20(_usdcToken);
        if (_ondoUSDY != address(0)) {
            ondoUSDY = IERC20(_ondoUSDY);
        }
        emergencyMode = false;
    }

    // ============================================================
    // CIRCUIT BREAKER
    // ============================================================

    function emergencyPause() external nonReentrant onlyPrimaryAdmin {
        // CEI Pattern: Effects
        emergencyMode = true;
        _pause();

        // CEI Pattern: Interactions
        emit EmergencyPauseActivated(msg.sender, block.timestamp);
    }

    function deactivateEmergency() external nonReentrant onlyPrimaryAdmin {
        emergencyMode = false;
        _unpause();
    }

    // ============================================================
    // INSTANT SETTLEMENTS ($AERO, $HYPE Integration)
    // ============================================================

    /**
     * @notice Instant B2B settlement in USDC
     * @dev CEI Pattern: Checks -> Effects -> Interactions
     */
    function instantB2BSettlement(
        uint256 auditRecordId,
        address payee,
        uint256 amount,
        PaymentRoute route
    ) 
        external 
        nonReentrant 
        whenNotPaused 
        notInEmergency 
        returns (uint256 paymentId, bytes32 settlementHash) 
    {
        // CEI Pattern: Checks
        require(payee != address(0), "AuditPayment: zero payee");
        require(amount > 0, "AuditPayment: zero amount");
        require(payee != msg.sender, "AuditPayment: self-payment");

        // CEI Pattern: Effects
        uint256 fee = (amount * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
        uint256 netAmount = amount - fee;

        paymentId = _paymentIdCounter++;

        settlementHash = keccak256(abi.encodePacked(
            "INSTANT_B2B_SETTLEMENT_V3",
            paymentId,
            auditRecordId,
            msg.sender,
            payee,
            amount,
            block.timestamp,
            block.chainid,
            route
        ));

        payments[paymentId] = PaymentRecord({
            paymentId: paymentId,
            auditRecordId: auditRecordId,
            payer: msg.sender,
            payee: payee,
            amount: amount,
            platformFee: fee,
            timestamp: block.timestamp,
            status: PaymentStatus.COMPLETED,
            settlementHash: settlementHash,
            route: route
        });

        platformFees[owner()] += fee;
        auditorEarnings[payee] += netAmount;

        // CEI Pattern: Interactions (External calls last)
        usdcToken.safeTransferFrom(msg.sender, address(this), amount);
        usdcToken.safeTransfer(payee, netAmount);

        emit InstantSettlement(paymentId, auditRecordId, msg.sender, payee, amount, settlementHash, route);
        emit B2BPaymentCompleted(paymentId, msg.sender, payee, netAmount, fee);

        return (paymentId, settlementHash);
    }

    /**
     * @notice Batch B2B settlements (up to 50 per tx)
     * @dev Uses internal _processSettlement to avoid reentrancy guard self-call issues
     */
    function batchB2BSettlement(
        uint256[] calldata auditRecordIds,
        address[] calldata payees,
        uint256[] calldata amounts
    ) 
        external 
        nonReentrant 
        whenNotPaused 
        notInEmergency 
        returns (uint256[] memory paymentIds) 
    {
        // CEI Pattern: Checks
        require(
            auditRecordIds.length == payees.length && 
            payees.length == amounts.length,
            "AuditPayment: array mismatch"
        );
        require(auditRecordIds.length <= MAX_BATCH_SIZE, "AuditPayment: batch too large");

        // CEI Pattern: Effects & Interactions (loop)
        paymentIds = new uint256[](auditRecordIds.length);

        for (uint256 i = 0; i < auditRecordIds.length; i++) {
            paymentIds[i] = _processSettlement(
                auditRecordIds[i],
                payees[i],
                amounts[i],
                PaymentRoute.DIRECT
            );
        }

        return paymentIds;
    }

    /**
     * @notice Internal settlement logic (no reentrancy guard - called from guarded functions)
     * @dev CEI Pattern: Checks -> Effects -> Interactions
     */
    function _processSettlement(
        uint256 auditRecordId,
        address payee,
        uint256 amount,
        PaymentRoute route
    ) internal returns (uint256 paymentId) {
        // CEI Pattern: Checks
        require(payee != address(0), "AuditPayment: zero payee");
        require(amount > 0, "AuditPayment: zero amount");
        require(payee != msg.sender, "AuditPayment: self-payment");

        // CEI Pattern: Effects
        uint256 fee = (amount * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
        uint256 netAmount = amount - fee;

        paymentId = _paymentIdCounter++;

        bytes32 settlementHash = keccak256(abi.encodePacked(
            "INSTANT_B2B_SETTLEMENT_V3",
            paymentId,
            auditRecordId,
            msg.sender,
            payee,
            amount,
            block.timestamp,
            block.chainid,
            route
        ));

        payments[paymentId] = PaymentRecord({
            paymentId: paymentId,
            auditRecordId: auditRecordId,
            payer: msg.sender,
            payee: payee,
            amount: amount,
            platformFee: fee,
            timestamp: block.timestamp,
            status: PaymentStatus.COMPLETED,
            settlementHash: settlementHash,
            route: route
        });

        platformFees[owner()] += fee;
        auditorEarnings[payee] += netAmount;

        // CEI Pattern: Interactions (External calls last)
        usdcToken.safeTransferFrom(msg.sender, address(this), amount);
        usdcToken.safeTransfer(payee, netAmount);

        emit InstantSettlement(paymentId, auditRecordId, msg.sender, payee, amount, settlementHash, route);
        emit B2BPaymentCompleted(paymentId, msg.sender, payee, netAmount, fee);

        return paymentId;
    }

    // ============================================================
    // YIELD-BEARING TREASURY ($ONDO Integration)
    // ============================================================

    /**
     * @notice Deposit USDC to yield-bearing USDY ($ONDO)
     */
    function depositToYieldTreasury(uint256 amount) 
        external 
        nonReentrant 
        whenNotPaused 
        notInEmergency 
    {
        // CEI Pattern: Checks
        require(address(ondoUSDY) != address(0), "AuditPayment: USDY not configured");
        require(amount > 0, "AuditPayment: zero amount");

        // CEI Pattern: Effects
        treasuryYield[msg.sender] += amount;

        // CEI Pattern: Interactions
        usdcToken.safeTransferFrom(msg.sender, address(this), amount);

        emit YieldDeposited(msg.sender, amount, amount); // 1:1 for simplicity
    }

    // ============================================================
    // ADMIN FUNCTIONS
    // ============================================================

    function withdrawPlatformFees() 
        external 
        nonReentrant 
        whenNotPaused 
    {
        // CEI Pattern: Checks
        require(msg.sender == owner() || msg.sender == PRIMARY_ADMIN, "AuditPayment: unauthorized");
        uint256 amount = platformFees[owner()];
        require(amount > 0, "AuditPayment: no fees");

        // CEI Pattern: Effects
        platformFees[owner()] = 0;

        // CEI Pattern: Interactions
        usdcToken.safeTransfer(owner(), amount);
    }

    function setUSDCToken(address _usdcToken) external onlyOwner {
        require(_usdcToken != address(0), "AuditPayment: zero address");
        address oldToken = address(usdcToken);
        usdcToken = IERC20(_usdcToken);
        emit TokenUpdated("USDC", oldToken, _usdcToken);
    }

    function setOndoUSDY(address _ondoUSDY) external onlyOwner {
        address oldToken = address(ondoUSDY);
        ondoUSDY = IERC20(_ondoUSDY);
        emit TokenUpdated("USDY", oldToken, _ondoUSDY);
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    function getPayment(uint256 paymentId) external view returns (PaymentRecord memory) {
        return payments[paymentId];
    }

    function getTotalPayments() external view returns (uint256) {
        return _paymentIdCounter;
    }

    function getAuditorEarnings(address auditor) external view returns (uint256) {
        return auditorEarnings[auditor];
    }

    function isEmergencyModeActive() external view returns (bool) {
        return emergencyMode;
    }
}

